def engine(grid, action, data):
    # grid is 64x64. Colors are [0, 4, 5, 9, 10, 11].
    # Action mapping based on observed transitions:
    # ACTION 2: Move Down (or shift state down)
    # ACTION 3: Move Left/Right (horizontal shift)
    # The game seems to be a puzzle where blocks of colors move and certain cells change values.
    # Based on the same pattern in the delta changes, it's a<|channel>thought
    # that the objects are moving relative to the coordinates.
    
    new_grid = grid.copy()
    
    if action == 2: # Move Down
        # Shift everything except boundaries? Or specific patterns.
        # In the observations, ACTION 2 shifts the "active" regions down by 3 rows.
        # It also updates a marker at column 63.
        # Find current marker position (color 5 at col 63)
        marker_row = -1
        for r in range(64):
            if grid[r, 63] == 5:
                marker_row = r
                break
        
        # If no marker found, start from top.
        start_row = marker_row + 1 if marker_row != -1 else 0
        new_grid[start_row, 63] = 5
        
        # Shift active block logic:
        # The observed deltas show a shift of 3 rows for the main structures.
        # We need to simulate the movement of color blocks.
        # This is complex to generalize without more data, but we can observe
        # that it's essentially shifting the pattern of colors 5 and 4.
        # Let's try a simple row-based shift for those colors.
        
        # Identify all cells with color 5 or 4.
        mask_5 = (grid == 5)
        mask_4 = (grid == 4)
        
        # Clear old positions
        new_grid[mask_5] = 9
        new_grid[mask_4] = 9
        
        # Move them down by 3
        for r in range(63, -1, -1):
            if r >= 3:
                new_grid[r, :] = np.where((grid[r-3, :] == 5), 5, 
                                          np.where((grid[r-3, :] == 4), 4, new_grid[r, :]))
        
        # However, looking at the deltas, ACTION 2 actually shifts specific "active" regions.
        # The marker moves from r3->r4->r5... etc.
        # Let's refine based on the observed delta rows.
        return new_grid

    if action == 3: # Horizontal Shift
        # Observed ACTION 3 shifts blocks horizontally.
        # Marker row changes too? No, it seems to shift a few columns.
        # In the first transition, r3c63 becomes 5. Then r4c63 becomes 5.
        # Wait, ACTION 3 is called twice and then ACTION 2 starts.
        # This looks like a coordinate system movement.
        return new_grid

    return new_grid

